import {createVehicleHUD} from '../vehicle-hud.mjs';
import {createAccessoryState,setAccessoryEnabled,accessoryAction,stepAccessories} from '../rov-accessory-data.mjs';
import {createAccessoryPanel} from '../rov-accessory-panel.mjs';
import {createTank} from './tank.mjs?v=free-ax';
import {movementCodes,cycleLight,stepSpeed,normalizeHeading,readPilotKeys} from './controls.mjs?v=free-ax';
import {createPose,step} from './physics.mjs?v=free-ax';
const $=id=>document.getElementById(id),pressed=new Set(),movement=movementCodes;let pose=createPose(),armed=false,hold=false,recording=false,last=performance.now(),lastSample=0,rows=[];let speedPercent=25,stabilizing=false;const opts={view:'third',waves:true,lights:0};const storage='rovTankTrialV2';try{rows=JSON.parse(localStorage.getItem(storage)||'[]');if(!Array.isArray(rows))rows=[];}catch{}rows=rows.slice(0,20000);
const accessories=createAccessoryState();
const accessoryContext=()=>({armed,depth:pose.depth,speed:Math.hypot(pose.vx,pose.vz,pose.vd),position:{x:pose.x,y:-pose.depth,z:pose.z}});
const toolPanel=createAccessoryPanel($('accessory-panel'),{onToggle:(id,on)=>{setAccessoryEnabled(accessories,id,on);log('tool_mount',{id,on});toolPanel.update(accessories);},onAction:action=>{const result=accessoryAction(accessories,action,accessoryContext());log('tool_action',{action,...result});toolPanel.update(accessories);}});toolPanel.update(accessories);
function toggleTools(){const open=$('accessory-panel').hidden;$('accessory-panel').hidden=!open;$('accessory-toggle').setAttribute('aria-expanded',String(open));}
$('accessory-toggle').onclick=toggleTools;
const tank=createTank($('scene'),$('render-status')),dashboard=createVehicleHUD($('vehicle-dashboard'));
$('free-recenter').onclick=()=>tank.recenter();
function log(kind,data){if(recording&&rows.length<20000)rows.push({seq:rows.length+1,utc:new Date().toISOString(),sim_time_s:+pose.t.toFixed(3),kind,data,synthetic:true,command_sent:false});$('event-count').textContent=rows.length+' records';}
function persist(){try{localStorage.setItem(storage,JSON.stringify(rows));}catch{$('feedback').textContent='Browser storage full. Download the trial now.';}}
function inputs(){const active=armed&&document.hasFocus()&&!document.hidden;return readPilotKeys(pressed,active,speedPercent);}
function release(reason){stabilizing=false;pressed.clear();log('release',{reason});}
function disarm(reason){armed=false;hold=false;stepAccessories(accessories,0,accessoryContext());release(reason);paintArm();$('mode').textContent='Manual';$('mode').setAttribute('aria-pressed','false');}
function toggleArm(){const next=!armed;disarm('arm changed');armed=next;paintArm();log('arm',{armed});}
function paintArm(){$('mode').disabled=!armed;$('stabilize').disabled=!armed;document.querySelectorAll('[data-yaw]').forEach(b=>b.disabled=!armed);$('unlock').textContent=armed?'● Armed · Space to disarm':'○ Disarmed · Space to arm';$('unlock').setAttribute('aria-pressed',String(armed));}
function setLights(){opts.lights=cycleLight(opts.lights);$('lights').textContent='☀ Light '+opts.lights+'%';$('lights').setAttribute('aria-pressed',String(opts.lights>0));log('lights',{percent:opts.lights});}
function setSpeed(delta){speedPercent=stepSpeed(speedPercent,delta);$('speed-level').textContent=speedPercent+'%';$('speed-down').disabled=speedPercent===25;$('speed-up').disabled=speedPercent===100;log('speed_limit',{percent:speedPercent});}
$('speed-down').onclick=()=>setSpeed(-1);$('speed-up').onclick=()=>setSpeed(1);setSpeed(0);
$('unlock').onclick=toggleArm;
function stabilize(){if(!armed)return;for(const c of ['KeyQ','KeyE','KeyT','KeyV','KeyZ','KeyX'])pressed.delete(c);stabilizing=true;log('self_stabilize',{heading:pose.yaw});}
$('stabilize').onclick=stabilize;
function setView(view){opts.view=view;$('viewer').dataset.view=view;$('vehicle-dashboard').hidden=view!=='close';$('free-camera-help').hidden=view!=='free';document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)));$('viewer').setAttribute('aria-label',view+' ROV view and keyboard control');$('scene').setAttribute('aria-label',view+' ROV view in wave tank');log('camera',{view});}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
for(const node of document.querySelectorAll('[data-yaw]')){
 const code=Number(node.dataset.yaw)>0?'KeyX':'KeyZ';
 const down=()=>{if(!armed)return;stabilizing=false;pressed.add(code);};
 const up=()=>{pressed.delete(code);};
 node.onpointerdown=e=>{node.setPointerCapture(e.pointerId);down();};node.onpointerup=up;node.onpointercancel=up;node.onlostpointercapture=up;node.onblur=up;
 node.onkeydown=e=>{if(e.code==='Enter'){e.preventDefault();e.stopPropagation();if(!e.repeat)down();}};
 node.onkeyup=e=>{if(e.code==='Enter'){e.preventDefault();e.stopPropagation();up();}};
}

for(const [id,fn,label]of[['rc-enable',toggleArm,'Arm or disarm simulation'],['rc-light',setLights,'Cycle light level']]){const node=$(id);node.setAttribute('role','button');node.setAttribute('tabindex','0');node.setAttribute('aria-label',label);node.addEventListener('click',fn);node.addEventListener('keydown',e=>{if(e.code==='Enter'){e.preventDefault();e.stopPropagation();if(!e.repeat)fn();}});node.addEventListener('keyup',e=>{if(e.code==='Enter'){e.preventDefault();e.stopPropagation();}});}
const compassTicks=[];for(let i=0;i<23;i++){const tick=document.createElement('span');tick.className='compass-tick';tick.innerHTML='<i></i><span></span>';$('compass-tape').append(tick);compassTicks.push(tick);}
function paintCompass(heading){const h=normalizeHeading(heading),base=Math.floor(h/5)*5,labels={0:'N',45:'NE',90:'E',135:'SE',180:'S',225:'SW',270:'W',315:'NW'};compassTicks.forEach((tick,i)=>{const a=base+(i-11)*5,n=normalizeHeading(a);tick.style.left=(50+(a-h)*.85)+'%';tick.lastChild.textContent=labels[n]??n;tick.classList.toggle('cardinal',n%45===0);});$('compass-value').textContent=String(Math.round(h)%360).padStart(3,'0')+'°';$('compass').setAttribute('aria-label','ROV simulated heading '+h.toFixed(1)+' degrees');}

window.addEventListener('keydown',e=>{if(e.code!=='Space'||e.target.closest('input,textarea,select,[contenteditable]')||e.ctrlKey||e.metaKey||e.altKey)return;e.preventDefault();e.stopPropagation();if(!e.repeat)toggleArm();},true);
window.addEventListener('keyup',e=>{if(e.code==='Space'&&!e.target.closest('input,textarea,select,[contenteditable]')){e.preventDefault();e.stopPropagation();}},true);
window.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,[contenteditable]')||e.ctrlKey||e.metaKey||e.altKey)return;if(['KeyK','KeyU','KeyF','BracketLeft','BracketRight','Escape','Digit0','Numpad0','Digit1','Digit2','Digit3','Digit4'].includes(e.code)){e.preventDefault();if(e.repeat)return;if(e.code==='KeyK')toggleTools();else if(e.code==='Digit0'||e.code==='Numpad0')stabilize();else if(['Digit1','Digit2','Digit3','Digit4'].includes(e.code))setView(['first','close','third','free'][Number(e.code.slice(-1))-1]);else if(e.code==='KeyU')toggleArm();else if(e.code==='KeyF')setLights();else if(e.code==='Escape')disarm('stop');else setSpeed(e.code==='BracketLeft'?-1:1);return;}if(movement.has(e.code)){e.preventDefault();if(armed&&!pressed.has(e.code)){if(['KeyQ','KeyE','KeyT','KeyV','KeyZ','KeyX'].includes(e.code))stabilizing=false;pressed.add(e.code);log('key_down',{key:e.code});}}});window.addEventListener('keyup',e=>{if(movement.has(e.code)){e.preventDefault();pressed.delete(e.code);log('key_up',{key:e.code});}});window.addEventListener('blur',()=>disarm('blur'));document.addEventListener('visibilitychange',()=>{if(document.hidden){disarm('hidden');stopRecord();}});window.addEventListener('pagehide',()=>{disarm('pagehide');stopRecord();tank.dispose();toolPanel.dispose();dashboard.dispose();});
$('mode').onclick=()=>{if(!armed)return;hold=!hold;$('mode').textContent=hold?'Depth hold · SIM':'Manual';$('mode').setAttribute('aria-pressed',hold);log('mode',{depth_hold:hold});};
$('lights').onclick=setLights;
$('waves').onclick=()=>{opts.waves=!opts.waves;$('waves').textContent='Waves '+(opts.waves?'on':'off');$('waves').setAttribute('aria-pressed',String(opts.waves));};
$('reset').onclick=()=>{log('reset',{});pose=createPose();Object.assign(accessories,createAccessoryState());speedPercent=25;setSpeed(0);opts.lights=100;setLights();armed=false;hold=false;release('reset');paintArm();paintArm();$('mode').textContent='Manual';$('mode').setAttribute('aria-pressed',false);};
function recordUI(){ $('record').setAttribute('aria-pressed',recording);$('record').setAttribute('aria-label',recording?'Stop recording simulation':'Start recording simulation');$('record').textContent=recording?'■':'●';$('record-status').textContent=recording?'RECORDING':'RECORD TRIAL';$('download').disabled=!rows.length;$('rc-record').setAttribute('fill',recording?'#ff4653':'#652f36');}
function stopRecord(){if(recording){log('session_stop',{});recording=false;persist();recordUI();$('feedback').textContent='Trial saved locally. Download log.';}}
$('record').onclick=()=>{if(recording)stopRecord();else{rows=[];recording=true;log('session_start',{model:'illustrative water-coupled dynamics',tank_m:[6,12,3],rc3_mapping:'custom WASD translation, QE roll, RC heave, TV pitch; ZX yaw; Space arm/disarm; 0 levels attitude; F lights; brackets speed',speed_percent:speedPercent});recordUI();$('feedback').textContent='Recording synthetic motion and keyboard controls.';}};
$('download').onclick=()=>{const blob=new Blob([rows.map(x=>JSON.stringify(x)).join('\n')+'\n'],{type:'application/x-ndjson'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='rov_wave_tank_'+Date.now()+'.jsonl';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function frame(now){const dt=Math.min(.05,(now-last)/1000);last=now;const a=inputs();step(pose,a,dt,opts.waves,hold&&armed,stabilizing&&armed);if(stabilizing&&Math.abs(pose.roll)<.2&&Math.abs(pose.pitch)<.2&&Math.abs(pose.rollRate??0)<.7&&Math.abs(pose.pitchRate??0)<.7){pose.roll=0;pose.pitch=0;pose.rollRate=0;pose.pitchRate=0;stabilizing=false;}$('stabilize').textContent=stabilizing?'0 · Leveling…':'0 · Self-stabilize';$('stabilize').setAttribute('aria-pressed',String(stabilizing));opts.thrusters=armed&&(stabilizing||hold||['forward','strafe','vertical','yaw','pitch','roll'].some(k=>Math.abs(a[k])>.001));stepAccessories(accessories,dt,accessoryContext());tank.draw(pose,{...opts,dt,accessories});toolPanel.update(accessories);if(opts.view==='close')dashboard.update({vehicle:'ROV',armed,speed:Math.hypot(pose.vx,pose.vz,pose.vd),heading:pose.yaw,level:pose.depth,pitch:pose.pitch,roll:pose.roll,vertical:-pose.vd,drive:speedPercent,lights:opts.lights,battery:pose.battery,tether:Math.hypot(pose.x+2.9,pose.depth+.23,pose.z+.15-5.6),x:pose.x,z:pose.z,note:pose.boundary?'Tank boundary':hold?'Depth hold':stabilizing?'Self-leveling':'Manual'});$('depth').textContent=pose.depth.toFixed(2);$('heading').textContent=normalizeHeading(pose.yaw).toFixed(0);paintCompass(pose.yaw);$('attitude').textContent=pose.pitch.toFixed(0)+'° / '+pose.roll.toFixed(0)+'°';$('speed').textContent=Math.hypot(pose.vx,pose.vz,pose.vd).toFixed(2);$('battery').textContent=pose.battery.toFixed(0)+'%';$('clock').textContent=new Date().toISOString().slice(11,19);$('left-stick').setAttribute('transform',`translate(${a.roll*22},${-a.vertical*22})`);$('right-stick').setAttribute('transform',`translate(${a.strafe*22},${-a.forward*22})`);for(const [id,v] of [['lx',a.roll],['ly',a.vertical],['rx',a.strafe],['ry',a.forward]])$(id).textContent=(v>0?'+':'')+Math.round(v*100)+'%';$('rc-enable').setAttribute('fill',armed?'#4eae8d':'#333d43');$('rc-light').setAttribute('fill',opts.lights===100?'#fff3a0':opts.lights===50?'#ddc434':'#ae9c1a');$('rc-light').setAttribute('aria-label','Cycle light level, currently '+opts.lights+' percent');$('rc-enable').setAttribute('aria-pressed',String(armed));$('yaw-command').textContent=(a.yaw>0?'+':'')+Math.round(a.yaw*100)+'%';$('pitch-command').textContent=(a.pitch>0?'+':'')+Math.round(a.pitch*100)+'%';document.querySelectorAll('[data-code]').forEach(k=>k.classList.toggle('pressed',pressed.has(k.dataset.code)));const wheel=$('rc-pitch-wheel');if(wheel)wheel.style.opacity=a.pitch?'1':'.65';$('enable-badge').textContent=armed?(opts.thrusters?'THRUST ACTIVE':'ARMED · IDLE'):'DISARMED';$('enable-badge').classList.toggle('active',a.armed);$('pilot-status').textContent=armed?'Armed · WASD move · Z/X yaw · Space disarms':(opts.waves?'Disarmed · Space to arm · waves remain active':'Disarmed · Space to arm · calm water');$('boundary').textContent=pose.boundary?'TANK BOUNDARY REACHED':hold?'DEPTH HOLD · SIM':'SIMULATED TELEMETRY';if(recording&&now-lastSample>200){lastSample=now;log('sample',{input:a,pose:{...pose},options:{...opts,speedPercent},accessories:{...accessories,enabled:{...accessories.enabled}},depth_hold:hold});if(rows.length>=20000)stopRecord();}requestAnimationFrame(frame);}
paintArm();recordUI();$('event-count').textContent=rows.length+' records';requestAnimationFrame(frame);window.parent.postMessage({type:'rov-simulation-ready'},location.origin);
